func (l *base) ps() (string, error) {
	cmd := `LANGUAGE=en_US.UTF-8 ps --no-headers --ppid 2 -p 2 --deselect -o pid,comm`
	r := l.exec(util.PrependProxyEnv(cmd), noSudo)
	if !r.isSuccess() {
		return "", xerrors.Errorf("Failed to SSH: %s", r)
	}
	return r.Stdout, nil
}

// pkgPs associates each running process with the scanned packages that own its
// executable or loaded files. Package ownership differs between distributions,
// so callers provide the appropriate lookup function.
func (l *base) pkgPs(getOwnerPkgs func([]string) (models.Packages, error)) error {
	stdout, err := l.ps()
	if err != nil {
		return xerrors.Errorf("Failed to ps: %w", err)
	}

	pidNames := l.parsePs(stdout)
	pidLoadedFiles := map[string][]string{}
	for pid := range pidNames {
		stdout, err := l.lsProcExe(pid)
		if err != nil {
			l.log.Debugf("Failed to exec /proc/%s/exe: %s", pid, err)
			continue
		}
		exePath, err := l.parseLsProcExe(stdout)
		if err != nil {
			l.log.Debugf("Failed to parse /proc/%s/exe: %s", pid, err)
			continue
		}
		if exePath = strings.TrimSpace(exePath); exePath != "" {
			pidLoadedFiles[pid] = append(pidLoadedFiles[pid], exePath)
		}

		stdout, err = l.grepProcMap(pid)
		if err != nil {
			l.log.Debugf("Failed to exec /proc/%s/maps: %s", pid, err)
			continue
		}
		for _, path := range l.parseGrepProcMap(stdout) {
			path = strings.TrimSpace(path)
			if path != "" {
				pidLoadedFiles[pid] = util.AppendIfMissing(pidLoadedFiles[pid], path)
			}
		}
	}

	pidListenPorts := map[string][]models.PortStat{}
	stdout, err = l.lsOfListen()
	if err != nil {
		// Listening-port discovery is best effort; process/package associations
		// remain useful when lsof is unavailable.
		l.log.Warnf("Failed to lsof: %+v", err)
	}
	for ipPort, pids := range l.parseLsOf(stdout) {
		portStat, err := models.NewPortStat(ipPort)
		if err != nil {
			l.log.Warnf("Failed to parse ip:port: %s, err: %+v", ipPort, err)
			continue
		}
		for _, pid := range pids {
			pidListenPorts[pid] = append(pidListenPorts[pid], *portStat)
		}
	}

	for pid, loadedFiles := range pidLoadedFiles {
		if len(loadedFiles) == 0 {
			continue
		}
		ownerPkgs, err := getOwnerPkgs(loadedFiles)
		if err != nil {
			l.log.Debugf("Failed to get package owners for process %s: %s", pid, err)
			continue
		}

		proc := models.AffectedProcess{
			PID:             pid,
			Name:            pidNames[pid],
			ListenPortStats: pidListenPorts[pid],
		}
		for key, pack := range ownerPkgs {
			pack.AffectedProcs = append(pack.AffectedProcs, proc)
			l.Packages[key] = pack
		}
	}
	return nil
}

func (l *base) parsePs(stdout string) map[string]string {
	pidNames := map[string]string{}
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		ss := strings.Fields(line)
		if len(ss) < 2 {
			continue
		}
		pidNames[ss[0]] = ss[1]
	}
	return pidNames
}

func (o *redhatBase) procPathToFQPN(execCommand string) (string, error) {
	execCommand = strings.Replace(execCommand, "\x00", " ", -1) // for CentOS6.9
	path := strings.Fields(execCommand)[0]
	cmd := `LANGUAGE=en_US.UTF-8 rpm -qf --queryformat "%{NAME}-%{EPOCH}:%{VERSION}-%{RELEASE}\n" ` + path
	r := o.exec(cmd, noSudo)
	if !r.isSuccess() {
		return "", xerrors.Errorf("Failed to SSH: %s", r)
	}
	fqpn := strings.TrimSpace(r.Stdout)
	return strings.Replace(fqpn, "-(none):", "-", -1), nil
}

func (o *redhatBase) getOwnerPkgs(paths []string) (models.Packages, error) {
	cleanPaths := make([]string, 0, len(paths))
	for _, path := range paths {
		if path = strings.TrimSpace(path); path != "" {
			cleanPaths = append(cleanPaths, path)
		}
	}
	if len(cleanPaths) == 0 {
		return models.Packages{}, nil
	}

	cmd := o.rpmQf() + strings.Join(cleanPaths, " ")
	r := o.exec(util.PrependProxyEnv(cmd), noSudo)
	// rpm exit code means `the number` of errors.
	// https://listman.redhat.com/archives/rpm-list/2005-July/msg00071.html
	// If we treat non-zero exit codes of `rpm` as errors,
	// we will be missing a partial package list we can get.
	return o.parseGetOwnerPkgs(r.Stdout)
}

func (o *redhatBase) parseGetOwnerPkgs(stdout string) (models.Packages, error) {
	ownerPkgs := models.Packages{}
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || isIgnorableRPMOwnerLine(line) {
			continue
		}
		pack, err := o.parseInstalledPackagesLine(line)
		if err != nil {
			return nil, xerrors.Errorf("Failed to parse rpm -qf line %q: %w", line, err)
		}
		key, installed, ok := o.findScannedOwnerPackage(pack)
		if !ok {
			o.log.Debugf("Package from rpm -qf is not in the scanned package list: %+v", pack)
			continue
		}
		ownerPkgs[key] = installed
	}
	if err := scanner.Err(); err != nil {
		return nil, xerrors.Errorf("Failed to read rpm -qf output: %w", err)
	}
	return ownerPkgs, nil
}

func (o *redhatBase) findScannedOwnerPackage(owner models.Package) (string, models.Package, bool) {
	for key, installed := range o.Packages {
		if installed.Name == owner.Name &&
			installed.Version == owner.Version &&
			installed.Release == owner.Release &&
			installed.Arch == owner.Arch {
			return key, installed, true
		}
	}

	// The package collection is keyed by name and therefore may contain only
	// one of several installed versions or architectures. Keep associating the
	// process with that scanned package when RPM reports another installed
	// instance of the same package name.
	if installed, ok := o.Packages[owner.Name]; ok {
		return owner.Name, installed, true
	}
	return "", models.Package{}, false
}

func isIgnorableRPMOwnerLine(line string) bool {
	line = strings.TrimSuffix(strings.TrimSpace(line), ".")
	for _, suffix := range []string{
		"Permission denied",
		"is not owned by any package",
		"No such file or directory",
	} {
		if strings.HasSuffix(line, suffix) {
			return true
		}
	}
	return false
}

